function Catalog({ items }) {
  const [q,setQ] = useState('');
  const matches = items.filter(p => p.name.toLowerCase().includes(q.toLowerCase()));
  return <><label>Search <input value={q} onChange={e=>setQ(e.target.value)} /></label>
    {matches.length ? matches.map(p => <ProductCard key={p.id} product={p} />) : <p 
role="status">No results</p>}</>;
}
